1	export type Item = {
2	  type: string;
3	  cursed?: boolean;
4	  enchantment?: number;
5	};
6	
7	export type Customer = {
8	  yearsWithMHPCO: number;
9	};
10	
11	export type Damage = {
12	  itemType: string;
13	  amount: number;
14	};
15	
16	export type Incident = {
17	  cause: string;
18	  damages: readonly Damage[];
19	};
20	
21	export type QuoteStep = {
22	  op: "quote";
23	  items: readonly Item[];
24	};
25	
26	export type ClaimStep = {
27	  op: "claim";
28	  // Zero-based index of the quote step that created the policy.
29	  policy: number;
30	  incident: Incident;
31	};
32	
33	export type Step = QuoteStep | ClaimStep;
34	
35	export type Scenario = {
36	  customer: Customer;
37	  steps: readonly Step[];
38	};
39	
40	export type QuoteResult = { premium: number };
41	export type ClaimResult = { payout: number; remainingCap: number };
42	
43	// One entry per scenario step, in order. Each step's `op` selects the shape.
44	export type StepResult = QuoteResult | ClaimResult;
45	
46	export type ScenarioResult = {
47	  results: StepResult[];
48	};
49	
50	const PROCESSING_FEE = 5;
51	
52	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
53	
54	const BASE_PREMIUMS: Record<string, number> = {
55	  sword: 100,
56	  amulet: 60,
57	  staff: 80,
58	  potion: 40,
59	  rune: 25,
60	  moonstone: 25,
61	};
62	
63	// Every percentage modifier is a delta computed against an *unmodified* base
64	// and summed with the others — modifiers never compound. Policy-wide ones use
65	// the policy base, item-specific ones the affected item's own base premium.
66	//
67	// Percentages stay in integer percent points: multiply first, divide by 100
68	// last. A float multiplier such as `base * 1.1` yields 110.00000000000001 for
69	// a sword and breaks the ceil. `(base * 10) / 100` gives exactly 10.
70	const percentOf = (amount: number, percent: number): number =>
71	  (amount * percent) / 100;
72	
73	const BLOCK_SIZE = 3;
74	const BLOCK_BASE_PREMIUM = 60;
75	
76	const countByType = (items: readonly Item[]): Map<string, number> => {
77	  const counts = new Map<string, number>();
78	
79	  for (const item of items) {
80	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
81	  }
82	
83	  return counts;
84	};
85	
86	const baseOfGroup = (type: string, count: number): number =>
87	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * BASE_PREMIUMS[type];
88	
89	const policyBaseOf = (items: readonly Item[]): number =>
90	  [...countByType(items)].reduce(
91	    (total, [type, count]) => total + baseOfGroup(type, count),
92	    0,
93	  );
94	
95	// A modifier rule: when `applies` holds for the subject, `percent` percent of
96	// the relevant base premium is added. A negative percent is a discount. Every
97	// rule whose predicate holds contributes; the deltas are summed, never
98	// compounded.
99	type ModifierRule<Subject> = {
100	  applies: (subject: Subject) => boolean;
101	  percent: number;
102	};
103	
104	const sumApplicablePercents = <Subject>(
105	  rules: ModifierRule<Subject>[],
106	  subject: Subject,
107	): number =>
108	  rules.reduce(
109	    (total, rule) => (rule.applies(subject) ? total + rule.percent : total),
110	    0,
111	  );
112	
113	// Policy-wide modifiers: each is a percentage of the policy base premium.
114	//
115	// Their subject is the *policy* — the circumstances under which this quote is
116	// issued — not the customer alone. Today those circumstances are just who is
117	// asking; rules that also depend on where the quote sits in the scenario read
118	// the field they need off the same subject.
119	type Policy = {
120	  customer: Customer;
121	  // Zero-based ordinal among the customer's quotes in this scenario.
122	  quoteOrdinal: number;
123	};
124	
125	const LOYALTY_YEARS_THRESHOLD = 2;
126	const LOYALTY_DISCOUNT_PERCENT = -20;
127	const FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT = -15;
128	
129	const POLICY_MODIFIER_RULES: ModifierRule<Policy>[] = [
130	  { applies: () => true, percent: FIRST_INSURANCE_SURCHARGE_PERCENT },
131	  {
132	    applies: ({ customer }) =>
133	      customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD,
134	    percent: LOYALTY_DISCOUNT_PERCENT,
135	  },
136	  {
137	    applies: ({ quoteOrdinal }) => quoteOrdinal > 0,
138	    percent: FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT,
139	  },
140	];
141	
142	const policyModifierDelta = (policyBase: number, policy: Policy): number =>
143	  percentOf(policyBase, sumApplicablePercents(POLICY_MODIFIER_RULES, policy));
144	
145	// Item-specific modifiers: each is a percentage of the affected item's own
146	// base premium.
147	const CURSE_SURCHARGE_PERCENT = 50;
148	const HIGH_ENCHANTMENT_THRESHOLD = 5;
149	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
150	
151	const ITEM_MODIFIER_RULES: ModifierRule<Item>[] = [
152	  { applies: (item) => item.cursed === true, percent: CURSE_SURCHARGE_PERCENT },
153	  {
154	    applies: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
155	    percent: HIGH_ENCHANTMENT_SURCHARGE_PERCENT,
156	  },
157	];
158	
159	const itemModifierDelta = (item: Item): number =>
160	  percentOf(
161	    BASE_PREMIUMS[item.type],
162	    sumApplicablePercents(ITEM_MODIFIER_RULES, item),
163	  );
164	
165	const quote = (items: readonly Item[], policy: Policy): number => {
166	  const policyBase = policyBaseOf(items);
167	  const modifiers =
168	    policyModifierDelta(policyBase, policy) +
169	    items.reduce((total, item) => total + itemModifierDelta(item), 0);
170	
171	  // Rounding is in the MHPCO's favour: premiums round up.
172	  return Math.ceil(policyBase + modifiers) + PROCESSING_FEE;
173	};
174	
175	// Insurance values are what an item is insured FOR, distinct from the base
176	// premium charged to insure it.
177	const INSURANCE_VALUES: Record<string, number> = {
178	  sword: 1000,
179	  amulet: 600,
180	  staff: 800,
181	  potion: 400,
182	  rune: 250,
183	  moonstone: 250,
184	};
185	
186	const DEDUCTIBLE_PER_DAMAGE = 100;
187	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
188	
189	const insuranceSumOf = (items: readonly Item[]): number =>
190	  items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0);
191	
192	// The deductible is charged once per damaged item, not once per incident.
193	const payoutForDamage = (damage: Damage): number =>
194	  damage.amount - DEDUCTIBLE_PER_DAMAGE;
195	
196	// What the scenario has established by the time a step runs. Threaded through
197	// the steps in order: each step reads it, and hands the next step the progress
198	// its own execution made.
199	type ScenarioProgress = {
200	  // How many quotes the customer has already been given. Only quote steps
201	  // advance this, so an op that is not a quote leaves it untouched.
202	  quotesSoFar: number;
203	  // Policies created by earlier quote steps, keyed by their step index — the
204	  // handle a later claim step names in its `policy` field.
205	  policies: Map<number, readonly Item[]>;
206	};
207	
208	// Runs one step against the progress so far, returning its result alongside
209	// the progress the *next* step inherits. Dispatch on `step.op` lives here:
210	// a new op is a new branch, and the loop below is unaffected.
211	const runStep = (
212	  step: Step,
213	  stepIndex: number,
214	  customer: Customer,
215	  progress: ScenarioProgress,
216	): { result: StepResult; progress: ScenarioProgress } => {
217	  if (step.op === "claim") {
218	    const insuredItems = progress.policies.get(step.policy) ?? [];
219	    const cap = CAP_MULTIPLE_OF_INSURANCE_SUM * insuranceSumOf(insuredItems);
220	    const payout = step.incident.damages.reduce(
221	      (total, damage) => total + payoutForDamage(damage),
222	      0,
223	    );
224	
225	    return {
226	      result: { payout, remainingCap: cap - payout },
227	      progress,
228	    };
229	  }
230	
231	  return {
232	    result: {
233	      premium: quote(step.items, {
234	        customer,
235	        quoteOrdinal: progress.quotesSoFar,
236	      }),
237	    },
238	    progress: {
239	      quotesSoFar: progress.quotesSoFar + 1,
240	      policies: new Map(progress.policies).set(stepIndex, step.items),
241	    },
242	  };
243	};
244	
245	export const runScenario = (scenario: Scenario): ScenarioResult => {
246	  const results: StepResult[] = [];
247	  let progress: ScenarioProgress = { quotesSoFar: 0, policies: new Map() };
248	
249	  for (const [stepIndex, step] of scenario.steps.entries()) {
250	    const stepRun = runStep(step, stepIndex, scenario.customer, progress);
251	
252	    results.push(stepRun.result);
253	    progress = stepRun.progress;
254	  }
255	
256	  return { results };
257	};
