const insuranceSumOf = (items: readonly Item[]): number =>
  items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0);

// A policy as a claim sees it: the items it covers, and how much of its cap
// is still available. Successive claims against the same policy draw the cap
// down, so `remainingCap` is state that outlives the claim step that reads it.
type IssuedPolicy = {
  items: readonly Item[];
  remainingCap: number;
};

const issuePolicy = (items: readonly Item[]): IssuedPolicy => ({
  items,
  remainingCap: CAP_MULTIPLE_OF_INSURANCE_SUM * insuranceSumOf(items),
});

// The damaged item the entry refers to, as covered by the policy. The special
// reimbursement clauses grade the payout by the item's own properties, so the
// damage amount alone is never enough to settle an entry.
const damagedItemOf = (
  policy: IssuedPolicy,
  damage: Damage,
): Item | undefined => policy.items.find((item) => item.type === damage.itemType);

// What a single damage entry reimburses, before the policy's cap is applied.
// The deductible is charged once per damaged item, not once per incident, so
// it belongs here rather than at the incident level.
const payoutForDamage = (damage: Damage, _item: Item | undefined): number =>
  damage.amount - DEDUCTIBLE_PER_DAMAGE;

// Settles one incident against a policy, returning the payout and the policy
// as it stands afterwards. The cap is drawn down here — that is what makes a
// second claim against the same policy see less headroom than the first.
const settleClaim = (
  policy: IssuedPolicy,
  incident: Incident,
): { payout: number; policy: IssuedPolicy } => {
  const reimbursement = incident.damages.reduce(
    (total, damage) => total + payoutForDamage(damage, damagedItemOf(policy, damage)),
    0,
  );

  // Rounding is in the MHPCO's favour: payouts round down, mirroring the
  // premium's round up.
  const payout = Math.floor(reimbursement);

  return {
    payout,
    policy: { ...policy, remainingCap: policy.remainingCap - payout },
  };
};

